            { subject: "Marathi", type: "Grand", tagText: "Mishra Vakya", question: "'जेव्हा मनात आत्मविश्वास असतो, तेव्हा यश निश्चित मिळते.' - या वाक्याचा प्रकार ओळखा.", options: ["केवळ वाक्य", "संयुक्त वाक्य", "मिश्र वाक्य", "आज्ञार्थी वाक्य"], answer: 2, explanation: "जेव्हा-तेव्हा या संकेतदर्शक उभयान्वयी अव्ययाने जोडलेले मुख्य व गौण वाक्य असल्याने हे मिश्र वाक्य आहे." },
            { subject: "English", type: "Grand", tagText: "Subject Verb", question: "Identify the grammatically correct sentence:", options: ["One of my friends have gone abroad.", "One of my friends has gone abroad.", "One of my friend has gone abroad.", "One of my friends are abroad."], answer: 1, explanation: "'One of + plural noun' takes a singular verb ('has gone abroad')." },
            { subject: "Maths", type: "Grand", tagText: "Circle Geometry", question: "वर्तुळाचा व्यास हा त्याच्या त्रिज्येच्या किती पट असतो?", options: ["निमपट", "दुप्पट (2r)", "तिप्पट", "समान"], answer: 1, explanation: "वर्तुळाचा व्यास (d) = 2 × त्रिज्या (r)." },
            { subject: "Science", type: "Grand", tagText: "Prism", question: "काचेच्या प्रिझममधून पांढरा प्रकाश गेल्यावर त्याचे सात रंगांत विभाजन होण्याच्या प्रक्रियेला काय म्हणतात?", options: ["परावर्तन", "प्रकाशाचे अपस्करण (Dispersion of Light)", "अपवर्तन", "शोषण"], answer: 1, explanation: "प्रकाशातील वेगवेगळ्या रंगांच्या तरंगांच्या वेगातील फरकामुळे त्याचे वर्णपंक्तीत पृथक्करण होते." },
            { subject: "Social Science", type: "Grand", tagText: "Father of Constitution", question: "भारतीय संविधानाची मसुदा समितीचे अध्यक्ष कोण होते?", options: ["डॉ. राजेंद्र प्रसाद", "डॉ. बाबासाहेब आंबेडकर", "पं. जवाहरलाल नेहरू", "सरदार वल्लभभाई पटेल"], answer: 1, explanation: "डॉ. बाबासाहेब आंबेडकर हे मसुदा समितीचे अध्यक्ष असून त्यांना संविधानाचे शिल्पकार मानले जाते." }
